/** One tuple type element. */
export type TupleElement =
    /** One non-spread tuple element. */
    | {
          readonly kind: "element";
          readonly label?: StringId;
          readonly value: LocalNodeId;
          readonly isOptional: boolean;
          readonly isReadonly: boolean;
      }
    /** One spread tuple element. */
    | {
          readonly kind: "spread";
          readonly label?: StringId;
          readonly value: LocalNodeId;
      }
    /** Malformed tuple element slot. */
    | {
          readonly kind: "error";
      }
;

export const TupleElement = {
    /** One non-spread tuple element. */
    element(label: StringId | undefined, value: LocalNodeId, isOptional: boolean, isReadonly: boolean): TupleElement {
        return { kind: "element", label, value, isOptional, isReadonly };
    },

    /** One spread tuple element. */
    spread(label: StringId | undefined, value: LocalNodeId): TupleElement {
        return { kind: "spread", label, value };
    },

    /** Malformed tuple element slot. */
    error(): TupleElement {
        return { kind: "error" };
    },

    /** Encode this value. */
    encode(writer: BinaryWriter, value: TupleElement): void {
        encodeTupleElement(writer, value);
    },

    /** Decode one TupleElement. */
    decode(reader: BinaryReader): TupleElement {
        return decodeTupleElement(reader);
    },

    /** Return this value as JSON. */
    toJson(value: TupleElement): Json {
        return toJsonTupleElement(value);
    },

    /** Return one TupleElement from one JSON value. */
    fromJson(value: Json): TupleElement {
        return fromJsonTupleElement(value);
    },
};

/** Encode one TupleElement. */
export function encodeTupleElement(writer: BinaryWriter, value: TupleElement): void {
    switch (value.kind) {
        case "element":
            writer.writeUnsigned(0);
            writer.writeOption(value.label, (value0) => {
                encodeStringId(writer, value0);
            });
            encodeLocalNodeId(writer, value.value);
            writer.writeBool(value.isOptional);
            writer.writeBool(value.isReadonly);
            return;
        case "spread":
            writer.writeUnsigned(1);
            writer.writeOption(value.label, (value0) => {
                encodeStringId(writer, value0);
            });
            encodeLocalNodeId(writer, value.value);
            return;
        case "error":
            writer.writeUnsigned(2);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one TupleElement. */
export function decodeTupleElement(reader: BinaryReader): TupleElement {
    const variant = reader.readNumber();

    switch (variant) {
        case 0: {
            const label = reader.readOption(() => decodeStringId(reader));
            const value = decodeLocalNodeId(reader);
            const isOptional = reader.readBool();
            const isReadonly = reader.readBool();

            return {
                kind: "element",
                ...(label === undefined ? {} : { label }),
                value,
                isOptional,
                isReadonly,
            };
        }
        case 1: {
            const label = reader.readOption(() => decodeStringId(reader));
            const value = decodeLocalNodeId(reader);

            return {
                kind: "spread",
                ...(label === undefined ? {} : { label }),
                value,
            };
        }
        case 2: {
            return { kind: "error" };
        }
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one TupleElement. */
export function toJsonTupleElement(value: TupleElement): Json {
    switch (value.kind) {
        case "element":
            return {
                kind: "element",
                ...(value.label === undefined ? {} : { label: toJsonStringId(value.label) }),
                value: toJsonLocalNodeId(value.value),
                isOptional: value.isOptional,
                isReadonly: value.isReadonly,
            };
        case "spread":
            return {
                kind: "spread",
                ...(value.label === undefined ? {} : { label: toJsonStringId(value.label) }),
                value: toJsonLocalNodeId(value.value),
            };
        case "error":
            return {
                kind: "error",
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one TupleElement from one JSON value. */
export function fromJsonTupleElement(value: Json): TupleElement {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "element":
            return {
                kind,
                label: jsonOptional(object, "label", (value) => fromJsonStringId(value)),
                value: fromJsonLocalNodeId(jsonField(object, "value")),
                isOptional: jsonBool(jsonField(object, "isOptional")),
                isReadonly: jsonBool(jsonField(object, "isReadonly")),
            };
        case "spread":
            return {
                kind,
                label: jsonOptional(object, "label", (value) => fromJsonStringId(value)),
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "error":
            return {
                kind,
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}

/** An argument to a runtime call or tree construct. */
export type Argument =
    /** Named argument. */
    | {
          readonly kind: "named";
          readonly name: Name;
          readonly value: LocalNodeId;
      }
    /** Labeled argument. */
    | {
          readonly kind: "labeled";
          readonly label: StringId;
          readonly value: LocalNodeId;
      }
    /** Positional argument. */
    | {
          readonly kind: "positional";
          readonly value: LocalNodeId;
      }
    /** Spread argument. */
    | {
          readonly kind: "spread";
          readonly label?: StringId;
          readonly value: LocalNodeId;
      }
    /** Malformed argument slot. */
    | {
          readonly kind: "error";
      }
;

export const Argument = {
    /** Named argument. */
    named(name: Name, value: LocalNodeId): Argument {
        return { kind: "named", name, value };
    },

    /** Labeled argument. */
    labeled(label: StringId, value: LocalNodeId): Argument {
        return { kind: "labeled", label, value };
    },

    /** Positional argument. */
    positional(value: LocalNodeId): Argument {
        return { kind: "positional", value };
    },

    /** Spread argument. */
    spread(label: StringId | undefined, value: LocalNodeId): Argument {
        return { kind: "spread", label, value };
    },

    /** Malformed argument slot. */
    error(): Argument {
        return { kind: "error" };
    },

    /** Encode this value. */
    encode(writer: BinaryWriter, value: Argument): void {
        encodeArgument(writer, value);
    },

    /** Decode one Argument. */
    decode(reader: BinaryReader): Argument {
        return decodeArgument(reader);
    },

    /** Return this value as JSON. */
    toJson(value: Argument): Json {
        return toJsonArgument(value);
    },

    /** Return one Argument from one JSON value. */
    fromJson(value: Json): Argument {
        return fromJsonArgument(value);
    },
};

/** Encode one Argument. */
export function encodeArgument(writer: BinaryWriter, value: Argument): void {
    switch (value.kind) {
        case "named":
            writer.writeUnsigned(0);
            encodeName(writer, value.name);
            encodeLocalNodeId(writer, value.value);
            return;
        case "labeled":
            writer.writeUnsigned(1);
            encodeStringId(writer, value.label);
            encodeLocalNodeId(writer, value.value);
            return;
        case "positional":
            writer.writeUnsigned(2);
            encodeLocalNodeId(writer, value.value);
            return;
        case "spread":
            writer.writeUnsigned(3);
            writer.writeOption(value.label, (value0) => {
                encodeStringId(writer, value0);
            });
            encodeLocalNodeId(writer, value.value);
            return;
        case "error":
            writer.writeUnsigned(4);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one Argument. */
export function decodeArgument(reader: BinaryReader): Argument {
    const variant = reader.readNumber();

    switch (variant) {
        case 0: {
            const name = decodeName(reader);
            const value = decodeLocalNodeId(reader);

            return {
                kind: "named",
                name,
                value,
            };
        }
        case 1: {
            const label = decodeStringId(reader);
            const value = decodeLocalNodeId(reader);

            return {
                kind: "labeled",
                label,
                value,
            };
        }
        case 2: {
            const value = decodeLocalNodeId(reader);

            return {
                kind: "positional",
                value,
            };
        }
        case 3: {
            const label = reader.readOption(() => decodeStringId(reader));
            const value = decodeLocalNodeId(reader);

            return {
                kind: "spread",
                ...(label === undefined ? {} : { label }),
                value,
            };
        }
        case 4: {
            return { kind: "error" };
        }
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one Argument. */
export function toJsonArgument(value: Argument): Json {
    switch (value.kind) {
        case "named":
            return {
                kind: "named",
                name: toJsonName(value.name),
                value: toJsonLocalNodeId(value.value),
            };
        case "labeled":
            return {
                kind: "labeled",
                label: toJsonStringId(value.label),
                value: toJsonLocalNodeId(value.value),
            };
        case "positional":
            return {
                kind: "positional",
                value: toJsonLocalNodeId(value.value),
            };
        case "spread":
            return {
                kind: "spread",
                ...(value.label === undefined ? {} : { label: toJsonStringId(value.label) }),
                value: toJsonLocalNodeId(value.value),
            };
        case "error":
            return {
                kind: "error",
            };
    }

    throw new SerdeError("unknown enum variant");
}

/** Return one Argument from one JSON value. */
export function fromJsonArgument(value: Json): Argument {
    const object = jsonObject(value);
    const kind = jsonString(jsonField(object, "kind"));

    switch (kind) {
        case "named":
            return {
                kind,
                name: fromJsonName(jsonField(object, "name")),
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "labeled":
            return {
                kind,
                label: fromJsonStringId(jsonField(object, "label")),
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "positional":
            return {
                kind,
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "spread":
            return {
                kind,
                label: jsonOptional(object, "label", (value) => fromJsonStringId(value)),
                value: fromJsonLocalNodeId(jsonField(object, "value")),
            };
        case "error":
            return {
                kind,
            };
    }

    throw new SerdeError(`unknown enum variant: ${kind}`);
}
